const records = $input.first().json.data?.items || [];
const out = [];
const skipped = [];
const now = new Date();

const pick = (fields, keys) => {
  for (const k of keys) {
    if (fields[k] !== undefined) return fields[k];
  }
  return undefined;
};

const toText = (v) => {
  if (v == null) return '';
  if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') return String(v).trim();
  if (Array.isArray(v)) {
    return v
      .map((x) => {
        if (x == null) return '';
        if (typeof x === 'string' || typeof x === 'number' || typeof x === 'boolean') return String(x).trim();
        if (typeof x === 'object') return (x.text || x.link || x.email || x.name || '').toString().trim();
        return '';
      })
      .filter(Boolean)
      .join(', ');
  }
  if (typeof v === 'object') return String(v.text || v.link || v.email || v.name || '').trim();
  return '';
};

const toEmails = (v) => {
  const t = toText(v).replace(/mailto:/gi, '');
  const arr = t.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [];
  return [...new Set(arr.map((x) => x.toLowerCase()))];
};

const requiredDaysByStatus = { 0: 0, 1: 3, 2: 7, 3: 15 };

for (const record of records) {
  const fields = record.fields || {};

  const companyName = toText(pick(fields, ['公司名', 'Company Name', '公司名称', '企业名称']));
  const website = toText(pick(fields, ['官网', 'Website', '公司网站']));
  const unreadEmails = toEmails(pick(fields, ['未读邮件', 'Unread Emails', '未读邮箱']));
  const readEmails = toEmails(pick(fields, ['已读邮件', 'Read Emails', '已读邮箱']));
  const followUpStatusRaw = toText(pick(fields, ['跟进状态1', 'Follow-up Status', '跟进状态'])) || '0';
  const lastFollowUp = toText(pick(fields, ['最后跟进时间', 'Last Follow-up Time', '上次跟进时间']));
  const lastOpenTime = toText(pick(fields, ['最后打开时间', 'Last Open Time', '跟进状态2']));
  const customerProfile = toText(pick(fields, ['客户画像', 'Customer Profile']));
  const region = toText(pick(fields, ['所属区域', 'Region']));
  const country = toText(pick(fields, ['国家', 'Country']));

  const followUpStatus = Number.parseInt(followUpStatusRaw, 10) || 0;

  const reasons = [];
  if (!companyName) reasons.push('missing company');
  if (!website) reasons.push('missing website');
  if (!unreadEmails.length) reasons.push('missing unread emails');
  if (followUpStatus >= 4) reasons.push('follow-up >= 4');

  if (reasons.length) {
    skipped.push({
      recordId: record.record_id,
      reasons,
      keys: Object.keys(fields),
      sample: { companyName, website, unreadEmails, followUpStatusRaw },
    });
    continue;
  }

  const lf = lastFollowUp ? new Date(lastFollowUp) : null;
  const lo = lastOpenTime ? new Date(lastOpenTime) : null;

  const daysSinceLastFollowUp =
    lf && !Number.isNaN(lf.getTime()) ? Math.floor((now - lf) / (1000 * 60 * 60 * 24)) : 9999;

  const followUpType =
    lo &&
    !Number.isNaN(lo.getTime()) &&
    (!lf || Number.isNaN(lf.getTime()) || lo > lf)
      ? 'immediate'
      : 'scheduled';

  const requiredDays = requiredDaysByStatus[followUpStatus] ?? 9999;
  if (followUpType === 'scheduled' && daysSinceLastFollowUp < requiredDays) {
    reasons.push(`not due: ${daysSinceLastFollowUp}d < ${requiredDays}d`);
  }

  if (reasons.length) {
    skipped.push({
      recordId: record.record_id,
      reasons,
      keys: Object.keys(fields),
      sample: { companyName, website, unreadEmails, followUpStatusRaw },
    });
    continue;
  }

  out.push({
    recordId: record.record_id,
    companyName,
    website,
    unreadEmails,
    readEmails,
    followUpStatus,
    lastFollowUp,
    lastOpenTime,
    customerProfile,
    region,
    country,
    followUpType,
    daysSinceLastFollowUp,
    requiredDays,
  });
}

if (out.length) return out.map((x) => ({ json: x }));

return [];

const inputJson = $input.first().json || {};

const getLocalHour = (date, timeZone) => {
  return Number(
    new Intl.DateTimeFormat('en-US', {
      timeZone,
      hour12: false,
      hour: '2-digit',
    }).format(date)
  );
};

if (inputJson.error || inputJson.executionStatus === 'error' || inputJson.errors) {
  const cd = $('Process Companies').first().json || {};
  const now = new Date();
  return [{
    json: {
      ...cd,
      country: 'Unknown',
      region: 'North America',
      timezone: 'America/New_York',
      localHour: getLocalHour(now, 'America/New_York'),
      shouldSendNow: true,
      customerProfile: 'Profile analysis unavailable - using fallback',
      emailSubject: `Following up with ${cd.companyName}`,
      emailBody: 'Hi, I would love to explore how we can support your team.',
      sendTime: now.toISOString(),
    }
  }];
}

const geminiOutput = inputJson.text || inputJson.output || '{}';
let parsedData = {};

try {
  const jsonMatch = geminiOutput.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsedData = JSON.parse(jsonMatch[0]);
  } else {
    const lines = geminiOutput.split('\n');
    lines.forEach((line) => {
      if (line.includes('Country:')) parsedData.country = line.split(':').slice(1).join(':').trim();
      if (line.includes('Region:')) parsedData.region = line.split(':').slice(1).join(':').trim();
      if (line.includes('Subject:')) parsedData.emailSubject = line.split(':').slice(1).join(':').trim();
      if (line.includes('Body:')) parsedData.emailBody = line.split(':').slice(1).join(':').trim();
    });
  }
} catch (error) {
  console.error('Parse error:', error);
}

const companyData = $('Process Companies').first().json;
const regionTimezoneMap = {
  'Asia': 'Asia/Singapore',
  'East-Aus': 'Australia/Sydney',
  'ME-Africa': 'Africa/Johannesburg',
  'Europe': 'Europe/Berlin',
  'North America': 'America/New_York',
  'South America': 'America/Sao_Paulo'
};

const region = parsedData.region || 'North America';
const timezone = regionTimezoneMap[region] || 'America/New_York';
const now = new Date();

const localHour = getLocalHour(now, timezone);
const isInSendWindow = localHour >= 9 && localHour < 17;
const forceDebugSend = true;
const shouldSendNow = forceDebugSend || companyData.followUpType === 'immediate' || isInSendWindow;

return [{
  json: {
    ...companyData,
    country: parsedData.country || 'Unknown',
    region,
    timezone,
    localHour,
    shouldSendNow,
    customerProfile: parsedData.customerProfile || 'Profile not available',
    emailSubject: parsedData.emailSubject || `Following up with ${companyData.companyName}`,
    emailBody: parsedData.emailBody || 'Hi, I would love to explore how we can support your team.',
    sendTime: shouldSendNow ? now.toISOString() : null,
  }
}];

// Expand unread emails into one item per target so emails can send sequentially
const company = $('Parse & Schedule Time').first().json;
const uniqueEmails = [...new Set((company.unreadEmails || []).map((email) => (email || '').trim()).filter((email) => email))];

return uniqueEmails.map((email, index) => ({
  json: {
    ...company,
    targetEmail: email,
    emailIndex: index,
    emailBodyHtml: `${(company.emailBody || '').replace(/\n/g, '<br>')}`
  }
}));

// Update Unread/Read email lists when Brevo reports an open event
const payload = $input.first().json || {};
const data = payload.data || {};
const record = data.record || (Array.isArray(data.records) ? data.records[0] : null) || {};
const fields = record.fields || data.fields || {};

const trackingData = $('Build Delivery Update').first().json;

const toEmailList = (value) => {
  if (value == null) return [];

  if (Array.isArray(value)) {
    const out = [];
    for (const item of value) {
      if (item == null) continue;
      if (typeof item === 'string') out.push(item);
      else if (typeof item === 'object') out.push(item.text || item.email || item.link || '');
      else out.push(String(item));
    }
    return out
      .map((x) => String(x).replace(/mailto:/gi, '').trim().toLowerCase())
      .filter(Boolean);
  }

  if (typeof value === 'object') {
    const one = (value.text || value.email || value.link || '').toString();
    return one
      .split(',')
      .map((x) => x.replace(/mailto:/gi, '').trim().toLowerCase())
      .filter(Boolean);
  }

  return String(value)
    .split(',')
    .map((x) => x.replace(/mailto:/gi, '').trim().toLowerCase())
    .filter(Boolean);
};

const unreadRaw = fields['未读邮件'] ?? fields['Unread Emails'] ?? null;
const readRaw = fields['已读邮件'] ?? fields['Read Emails'] ?? '';

let unreadList = [...new Set(toEmailList(unreadRaw))];
let readList = [...new Set(toEmailList(readRaw))];

const openedEmail = ((trackingData.openedEmail || trackingData.email || '') + '')
  .replace(/mailto:/gi, '')
  .trim()
  .toLowerCase();
const openedAt = ((trackingData.openedAt || trackingData.occurredAt || new Date().toISOString()) + '').toString();

if (openedEmail) {
  unreadList = unreadList.filter((email) => email !== openedEmail);
  if (!readList.includes(openedEmail)) readList.push(openedEmail);
}

const unreadLink = unreadList[0] ? { text: unreadList[0], link: 'mailto:' + unreadList[0], type: 'url' } : null;
const readText = readList.join(', ');

return [{
  json: {
    recordId: trackingData.recordId,
    unreadLink,
    readText,
    openedAt,
  }
}];

const payload = $input.first().json || {};
const body = payload.body ?? payload;
const events = Array.isArray(body) ? body : [body];

const toIso = (v) => {
  if (v == null || v === '') return new Date().toISOString();
  if (typeof v === 'number') {
    const ms = v > 1e12 ? v : v * 1000;
    return new Date(ms).toISOString();
  }
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? new Date().toISOString() : d.toISOString();
};

const normalizeEvent = (v) => {
  const raw = (v || '').toString().trim();
  const lower = raw.toLowerCase().replace(/\s+/g, '_');
  const compact = lower.replace(/_/g, '');
  if (compact === 'hardbounce' || compact === 'hardbounced') return 'hard_bounced';
  if (compact === 'softbounce' || compact === 'softbounced') return 'soft_bounced';
  if (compact === 'uniqueopened') return 'opened';
  if (compact === 'opened' || compact === 'open') return 'opened';
  if (compact === 'clicked' || compact === 'click') return 'clicked';
  return lower;
};

return events.map((e) => {
  const event = normalizeEvent(e.event || e.Event || e.type);
  const email = (e.email || e.to || e.recipient || '').toString();
  const messageId = (e['message-id'] || e.messageId || e.message_id || '').toString();
  const occurredAt = toIso(e.date || e.ts || e.timestamp || e.occurredAt);
  const reason = (e.reason || e['reason'] || e['error'] || e['description'] || '').toString();
  const url = (e.link || e.url || e.clickedUrl || e.clicked_url || e['click_url'] || '').toString();

  return {
    json: {
      event,
      email,
      messageId,
      occurredAt,
      reason,
      url
    }
  };
});

const evt = $('Parse Brevo Event').first().json || $input.first().json || {};
const search = $('Search Feishu By Email').first().json || {};
const items = search.data?.items || [];
const recordId = items[0]?.record_id || '';

const event = (evt.event || '').toString();
const occurredAt = (evt.occurredAt || '').toString();

return [{
  json: {
    recordId,
    email: (evt.email || '').toString(),
    event,
    occurredAt,
    reason: (evt.reason || '').toString(),
    url: (evt.url || '').toString(),
    openedEmail: event === 'opened' ? ((evt.email || '') + '').trim() : '',
    openedAt: event === 'opened' ? occurredAt : ''
  }
}];

let expectedToken = '';

try {
  expectedToken = (($vars && $vars.BREVO_WEBHOOK_TOKEN) || '').toString().trim();
} catch (e) {}

if (!expectedToken) {
  try {
    expectedToken = (($env && $env.BREVO_WEBHOOK_TOKEN) || '').toString().trim();
  } catch (e) {}
}

// Fallback to the currently configured webhook token for this instance.
if (!expectedToken) {
  expectedToken = '{{BREVO_WEBHOOK_TOKEN}}';
}

const headersRaw = $json.headers || {};
const headers = {};
for (const [k, v] of Object.entries(headersRaw)) {
  const key = (k || '').toString().toLowerCase();
  if (!key) continue;
  const value = Array.isArray(v) ? v.join(',') : (v ?? '').toString();
  headers[key] = value;
}

const query = $json.query || {};
const auth = (headers['authorization'] || '').trim();
const bearer = auth.toLowerCase().startsWith('bearer ') ? auth.slice(7).trim() : '';

const candidate = (
  headers['x-webhook-token'] ||
  headers['x-mailin-token'] ||
  headers['x-brevo-token'] ||
  headers['x-token'] ||
  (query.token ?? query.Token ?? query.TOKEN) ||
  bearer ||
  ''
).toString().trim();

const hasCandidate = Boolean(candidate);
const authorized = hasCandidate && candidate === expectedToken;

if (!authorized) {
  return [{
    json: {
      ...$json,
      authorized: false,
      responseCode: 401,
      responseBody: { status: 'unauthorized' },
    }
  }];
}

return [{
  json: {
    ...$json,
    authorized: true,
    tokenPresent: hasCandidate,
  }
}];

