const company = $input.first().json || {};

const companyName = (company.companyName || '').toString().trim();
const customerProfile = (company.customerProfile || '').toString().trim();
const region = (company.region || '').toString().trim() || 'North America';
const country = (company.country || '').toString().trim() || 'Unknown';

const emailSubject = (company.emailSubject || '').toString().trim() || (companyName ? `Following up with ${companyName}` : 'Following up');
const emailBody = (company.emailBody || '').toString().trim() || (
  customerProfile
    ? `Hi,\n\nI reviewed your business profile: ${customerProfile}\n\nIf it makes sense, I’d love to explore how we can support your team.\n\nBest regards,`
    : 'Hi,\n\nI would love to explore how we can support your team.\n\nBest regards,'
);

return [{
  json: {
    text: JSON.stringify({
      country,
      region,
      customerProfile,
      emailSubject,
      emailBody,
    })
  }
}];

const c = $('Process Companies').first().json || {};
const companyName = (c.companyName || 'the company').toString().trim();
const website = (c.website || $json.website || '').toString().trim();

const rawScraped = (($json.data && $json.data.markdown) || $json.markdown || ($json.data && $json.data.content) || '').toString();
const scraped = rawScraped.replace(/[{}]/g, ' ').slice(0, 12000);

let salesName = '';
let salesWhatsapp = '';
let yourWebsite = '';

try {
  salesName = (($vars && ($vars.SALES_NAME || $vars.sales_name)) || '').toString().trim();
  salesWhatsapp = (($vars && ($vars.SALES_WHATSAPP || $vars.sales_whatsapp)) || '').toString().trim();
  yourWebsite = (($vars && ($vars.YOUR_WEBSITE || $vars.your_website)) || '').toString().trim();
} catch (e) {}

if (!salesName) salesName = '[sales_name]';
if (!salesWhatsapp) salesWhatsapp = '[sales_whatsapp]';
if (!yourWebsite) yourWebsite = '[your_website]';

const prompt = [
  'You are an outbound B2B email copywriter for MEAN WELL products.',
  'Return STRICT JSON only with keys: country, region, customerProfile, emailSubject, emailBody.',
  '',
  'Business background:',
  '- We supply all MEAN WELL product lines.',
  '- We are a MEAN WELL distributor with 20 years of experience.',
  '- We serve 3000+ partners worldwide.',
  '- If customer needs other power supply brands, we can also support them.',
  '',
  'Mandatory email structure:',
  '1) Subject: create dynamically from customer/company research (must be relevant to their business).',
  `2) Salutation must be exactly: "Dear ${companyName} Team,"`,
  '3) Body order:',
  '   a) Greeting: hope they are doing well.',
  '   b) Brief intro: 20 years + 3000+ global partners.',
  '   c) Infer customer industry from website and state that we can provide customized product recommendations based on their needs.',
  '   d) Recommend 1-2 models/categories with reason linked to their likely needs.',
  '   e) Advantages section: choose by customer type using rules below.',
  '   f) Closing: look forward to cooperation and business growth.',
  '   g) End with exactly:',
  '      Best regards,',
  `      ${salesName}`,
  `      WhatsApp: ${salesWhatsapp}`,
  `      Website: ${yourWebsite}`,
  '',
  'Advantages library:',
  '1. 5%-15% lower pricing than market level.',
  '2. Safe logistics and on-time delivery.',
  '3. Duty-free channels in selected countries.',
  '4. Complete MEAN WELL technical support.',
  '5. Smooth import/export customs delivery.',
  '6. Customized power supply details on request.',
  '7. Global MEAN WELL after-sales support with authenticity traceability.',
  '',
  'Customer-type advantage selection rules (must follow):',
  '- Factory customer: emphasize cost + technical support + customization (prefer 1,4,6).',
  '- Engineering contractor/system integrator: emphasize technical support + after-sales (prefer 4,7, optional 6).',
  '- Trader/distributor: emphasize cost + lead time + customs + duty-free (prefer 1,2,5,3).',
  '',
  'Output rules:',
  '- region must be one of: Asia, East-Aus, ME-Africa, Europe, North America, South America.',
  '- 120-190 words for emailBody.',
  '- Professional and concise tone.',
  '- No markdown bullets in emailBody.',
  '- Do not output any extra keys, markdown, or commentary.',
  '',
  `Customer target: Company=${companyName}; Website=${website}`,
  '',
  'Website content:',
  scraped
].join('\n');

return [{
  json: {
    ...$json,
    geminiPrompt: prompt
  }
}];
